# Generated by manage.py generate_test_cases.
from bloomerp.models.automation import Workflow, WorkflowNode
from bloomerp.tests.base import (
    BloomerpComponentTestCase,
    ExpectedResult,
    RequestScenario,
)


class TestRenderWorkflowNodeSchemaPanelComponent(BloomerpComponentTestCase):
    """Tests function `render_workflow_node_schema_panel` from `bloomerp/components/automation/render_workflow_node.py`."""

    view_name = "components_automation_render_workflow_node_schema_panel"

    def setUp(self) -> None:
        super().setUp()
        workflow = Workflow.objects.create(name="Schema panel coverage")
        self.workflow_node = WorkflowNode.objects.create(
            workflow=workflow,
            type="FLOW",
            sub_type="FILTER_OBJECTS",
            parameters={"field": "status"},
        )
        
    def get_test_scenarios(self) -> list[RequestScenario]:
        return [
            RequestScenario(
                name="redirect anonymous users to login",
                query_params={"node_id": self.workflow_node.pk},
                expected=ExpectedResult(
                    status_code=302,
                    response_validators=lambda response: response.headers[
                        "Location"
                    ].startswith("/accounts/login/"),
                ),
            ),
            RequestScenario(
                name="render the resolved input and output schema",
                user=self.admin_user,
                query_params={"node_id": self.workflow_node.pk},
                expected=ExpectedResult(
                    response_validators=lambda response: (
                        response.context["incoming_schema"].label
                        == "No upstream input"
                        and response.context["incoming_schema"].value_type == "none"
                        and response.context["output_schema"].label
                        == "Filtered objects"
                        and response.context["output_schema"].value_type == "list"
                        and {
                            field.path
                            for field in response.context["output_schema"].fields
                        }
                        == {"input", "input.0"}
                    ),
                ),
            ),
        ]
